def longestStringChain(words):
    ws = sorted(words.split(","), key=len)
    best = {}
    ans = 1
    for w in ws:
        cur = 1
        for i in range(len(w)):
            c = w[:i] + w[i + 1:]
            if c in best and best[c] + 1 > cur:
                cur = best[c] + 1
        best[w] = cur
        if cur > ans:
            ans = cur
    return ans
